/*
 * A068501  Values m such that the consecutive pair parameters(m,m+1) generate
 *          Pythagorean triples whose odd terms are both prime.
 * https://oeis.org/A068501
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 20, u16 n <= 1312, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A068501 – values m such that the Pythagorean triple generated by
    the consecutive pair (m,m+1) has both odd terms prime.
    The odd terms are:
        a = 2m + 1
        c = 2m² + 2m + 1
    Only those m for which a and c are prime are stored.
    a(n) is the n‑th such m (a(1)=1, a(2)=2, a(3)=5, …).  */

#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

/* deterministic Miller–Rabin test for 64‑bit integers */
static inline bool isPrime64(uint64_t n)
{
    if (n < 2) return false;
    static const uint64_t small[] = {
        2ULL,3ULL,5ULL,7ULL,11ULL,13ULL,17ULL,19ULL,23ULL,29ULL,31ULL,37ULL
    };
    for (size_t i = 0; i < sizeof(small)/sizeof(small[0]); ++i) {
        uint64_t p = small[i];
        if (n == p) return true;
        if (n % p == 0) return false;
    }

    uint64_t d = n - 1, s = 0;
    while ((d & 1) == 0) { d >>= 1; ++s; }

    /* bases that make the test deterministic for all 64‑bit numbers */
    static const uint64_t bases[] = {
        2ULL,325ULL,9375ULL,28178ULL,450775ULL,9780504ULL,1795265022ULL
    };
    for (size_t i = 0; i < sizeof(bases)/sizeof(bases[0]); ++i) {
        uint64_t a = bases[i] % n;
        if (a == 0) continue;

        __uint128_t x = 1, p = d, base = a;
        while (p) {
            if (p & 1) x = (x * base) % n;
            base = (base * base) % n;
            p >>= 1;
        }
        if (x == 1 || x == n - 1) continue;

        bool composite = true;
        for (uint64_t r = 1; r < s; ++r) {
            x = (x * x) % n;
            if (x == n - 1) { composite = false; break; }
        }
        if (composite) return false;
    }
    return true;
}

/* cache of solved terms (as 64‑bit integers) */
static uint64_t *terms   = NULL;
static size_t  used      = 0;
static size_t  capacity  = 0;
static uint64_t lastFound = 0;

/* ------------------------------------------------------------ */
seq_t a(idx_t n)
{
    if (n == 0) return 0;                /* undefined, for safety */

    /* return cached value if already computed */
    if ((size_t)(n - 1) < used)
        return (seq_t)terms[n - 1];

    /* find more terms until we reach the requested index */
    for (; used < (size_t)n; ) {
        uint64_t m = lastFound + 1;      /* next candidate */
        bool ok = false;

        uint64_t aTerm = 2ULL * m + 1ULL;
        if (isPrime64(aTerm)) {
            __uint128_t tmp =
                (__uint128_t)2 * m * m + (__uint128_t)2 * m + 1;
            uint64_t cTerm = (uint64_t)tmp;
            if (isPrime64(cTerm)) ok = true;
        }

        lastFound = m;

        if (ok) {
            if (used == capacity) {          /* grow cache */
                size_t newCap = capacity ? capacity * 2 : 16;
                uint64_t *tmp = (uint64_t *)realloc(terms,
                                   newCap * sizeof(uint64_t));
                if (!tmp) exit(1);           /* allocation failed */
                terms   = tmp;
                capacity = newCap;
            }
            terms[used++] = m;                /* store the solution */
        }
    }

    return (seq_t)terms[n - 1];
}
